  ('74e44534-1412-4132-96c3-66bf9057e286', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', 'd183c093-dd11-4f93-95f4-bf73a17cc730', 'concept'::public.curated_course_node_type, 'Causal exclusion problem', null, 0),
