  ('a84366dc-6947-47b2-b972-f08bb4db7fee', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', 'cf13fee8-d6e9-45a8-8096-6600412ce108', 'concept'::public.curated_course_node_type, 'Bridge laws and reduction', null, 0),
