  ('3a25636c-c607-48be-9934-a05a943ebd57', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '18bc6ffe-2187-4fcd-960c-c2be6470b8f6', 'concept'::public.curated_course_node_type, 'Narrative and personal-level explanation', null, 2),
