  ('bfd8ec18-7db7-4523-b5c2-36fa849fab30', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', null, 'topic'::public.curated_course_node_type, 'Neuroscience, Cognitive Psychology, and Methods for Studying Mind', 'This topic gives students enough empirical literacy to evaluate claims from neuroscience, psychology, cognitive science, and brain imaging without reducing philosophy to data summary.', 10),
