  ('56621cf7-6ac0-4482-a171-83fe13a10248', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '83696a87-57f2-448f-861f-8319e8029705', 'concept'::public.curated_course_node_type, 'Lesions, stimulation, EEG, fMRI, and single-cell recording', null, 0),
  ('9be4f5e7-14bf-4fe1-96d6-c718c3e635d2', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '83696a87-57f2-448f-861f-8319e8029705', 'concept'::public.curated_course_node_type, 'Behavioral experiments and reaction time', null, 1),
  ('f5e14cc5-5c5a-4b4a-9000-31e32579ee64', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '83696a87-57f2-448f-861f-8319e8029705', 'concept'::public.curated_course_node_type, 'Computational modeling and cognitive tasks', null, 2),
  ('4f1a9928-2721-4c4d-9e84-fe1587c556df', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', 'bfd8ec18-7db7-4523-b5c2-36fa849fab30', 'subtopic'::public.curated_course_node_type, 'Cognitive systems', 'This subtopic connects philosophy with attention, memory, language, perception, and decision making.', 1),
  ('ecf38f4c-008a-42a2-aadc-54d798c8ef42', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '4f1a9928-2721-4c4d-9e84-fe1587c556df', 'concept'::public.curated_course_node_type, 'Attention and working memory', null, 0),
  ('6f5b078a-56b1-48ad-8577-ee391b5bcc44', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '4f1a9928-2721-4c4d-9e84-fe1587c556df', 'concept'::public.curated_course_node_type, 'Long-term memory and concepts', null, 1),
  ('a3ba0c9e-c228-43a0-9967-44ef6074abf8', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '4f1a9928-2721-4c4d-9e84-fe1587c556df', 'concept'::public.curated_course_node_type, 'Reasoning, problem solving, and decision making', null, 2),
  ('07606ffd-0722-4808-af3b-79eaf01ad1ed', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', 'bfd8ec18-7db7-4523-b5c2-36fa849fab30', 'subtopic'::public.curated_course_node_type, 'Methodological caution', 'Students learn to resist both armchair isolation and naive brain-scan triumphalism.', 2),
  ('ecbcbe51-7747-45f4-8245-7fbecfe8706f', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '07606ffd-0722-4808-af3b-79eaf01ad1ed', 'concept'::public.curated_course_node_type, 'Reverse inference and localization limits', null, 0),
  ('1d14404e-5e9f-4acf-8135-2ec30559ffd6', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '07606ffd-0722-4808-af3b-79eaf01ad1ed', 'concept'::public.curated_course_node_type, 'Replication and ecological validity', null, 1),
  ('c823d590-1fe6-467c-800f-0bccc80c2aaf', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '07606ffd-0722-4808-af3b-79eaf01ad1ed', 'concept'::public.curated_course_node_type, 'Philosophical interpretation of empirical results', null, 2),
  ('920db6a1-a238-4b4b-91a3-a5f72bc1d348', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', null, 'topic'::public.curated_course_node_type, 'Artificial Intelligence, Computation, and Machine Minds', 'Students examine whether machines can think, understand, be conscious, or possess agency, using classical AI, connectionism, contemporary deep learning, and language models as test cases.', 11),
  ('906e3133-012b-4dfe-bc56-ab17a79124e8', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '920db6a1-a238-4b4b-91a3-a5f72bc1d348', 'subtopic'::public.curated_course_node_type, 'Classical AI and computation', 'Students examine whether cognition is computation over representations.', 0),
  ('a77d596d-b545-4eaf-905e-0b186a33341c', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '906e3133-012b-4dfe-bc56-ab17a79124e8', 'concept'::public.curated_course_node_type, 'Turing test', null, 0),
  ('48907ad7-d6e7-4c32-a9a1-c0fb7432de2c', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '906e3133-012b-4dfe-bc56-ab17a79124e8', 'concept'::public.curated_course_node_type, 'Physical symbol systems', null, 1),
  ('a2e6e4fd-e317-439d-9720-6159f24eabcc', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '906e3133-012b-4dfe-bc56-ab17a79124e8', 'concept'::public.curated_course_node_type, 'Computation, implementation, and syntax', null, 2),
  ('721c0c5e-04b4-417e-aa66-20adb868a353', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '920db6a1-a238-4b4b-91a3-a5f72bc1d348', 'subtopic'::public.curated_course_node_type, 'Chinese room and understanding', 'This debate tests whether appropriate input-output behavior is enough for understanding.', 1),
  ('7b6f6a1c-791e-4d1b-aa7e-91c8b14025c3', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '721c0c5e-04b4-417e-aa66-20adb868a353', 'concept'::public.curated_course_node_type, 'Searle''s Chinese room', null, 0),
  ('14664162-ff2b-4e50-b66d-5178a7556672', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '721c0c5e-04b4-417e-aa66-20adb868a353', 'concept'::public.curated_course_node_type, 'Systems replies and robot replies', null, 1),
