  ('72a0b4d8-68b9-4a65-b95e-f77919a33740', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '920db6a1-a238-4b4b-91a3-a5f72bc1d348', 'subtopic'::public.curated_course_node_type, 'Contemporary AI and machine minds', 'Students evaluate deep learning and language models through philosophy of mind questions.', 2),
  ('299b4bf6-c758-49c1-9596-f209d937e7dd', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '72a0b4d8-68b9-4a65-b95e-f77919a33740', 'concept'::public.curated_course_node_type, 'Neural networks and representation', null, 0),
  ('5091f013-41b6-47a4-974a-eed4766be762', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '72a0b4d8-68b9-4a65-b95e-f77919a33740', 'concept'::public.curated_course_node_type, 'Transformers and large language models', null, 1),
  ('26535d67-f1cd-435d-b548-facd504ee370', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '72a0b4d8-68b9-4a65-b95e-f77919a33740', 'concept'::public.curated_course_node_type, 'Consciousness, agency, alignment, and moral status', null, 2),
  ('8c669aa9-8e4b-4bd0-a30d-fd3792f366e1', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', null, 'topic'::public.curated_course_node_type, 'Animal Minds, Other Minds, and Social Cognition', 'This topic expands the course beyond individual adult human minds by asking how we know other minds and how mindedness appears in animals, infants, groups, and social interaction.', 12),
  ('3fa6029b-4da0-492a-8e46-098f61ca1276', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '8c669aa9-8e4b-4bd0-a30d-fd3792f366e1', 'subtopic'::public.curated_course_node_type, 'Other minds', 'The problem of other minds asks how we know that anyone else has mental states.', 0),
  ('e4cd120f-60a7-4e44-ae0c-83f953d166d4', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '3fa6029b-4da0-492a-8e46-098f61ca1276', 'concept'::public.curated_course_node_type, 'Analogy and inference', null, 0),
  ('7734b1a5-627c-40a9-90d4-bd59cc4f551f', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '3fa6029b-4da0-492a-8e46-098f61ca1276', 'concept'::public.curated_course_node_type, 'Behavior and expression', null, 1);
