  ('7d52e089-e41b-4395-b78f-741cdc024ab1', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '5e3b01ab-f0fe-4baa-aee0-407ef095d0a0', 'concept'::public.curated_course_node_type, 'Brain privacy and neurotechnology', null, 0),
