  ('65f2c9dd-00a0-4dd4-8f2d-17f9f97abe14', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', '5e3b01ab-f0fe-4baa-aee0-407ef095d0a0', 'concept'::public.curated_course_node_type, 'AI companions, manipulation, and moral responsibility', null, 2),
