  ('18e8d3ec-a441-4179-8532-d0f032ed6ff9', 'f2a3b4c5-6d7e-4f20-9a90-0b1c2d3e4f20', 'a974be0c-1c98-434a-9375-cdc7ff4584ca', 'concept'::public.curated_course_node_type, 'Topic selection and problem framing', null, 0),
