update public.learning_paths
set
  title = 'Philosophy of Mind',
  goal = 'Philosophy of Mind',
  summary = 'Philosophy of Mind examines consciousness, mental states, intentionality, selfhood, agency, perception, emotion, cognition, artificial intelligence, and the relation between mind, brain, body, language, and world. Students reconstruct major arguments, evaluate theories of mind, use empirical work carefully, and write rigorous philosophical analyses of live debates about persons, machines, animals, and mental life.',
  data = $pmindjson${"slug": "philosophy-of-mind", "title": "Philosophy of Mind", "description": "Philosophy of Mind examines consciousness, mental states, intentionality, selfhood, agency, perception, emotion, cognition, artificial intelligence, and the relation between mind, brain, body, language, and world. Students reconstruct major arguments, evaluate theories of mind, use empirical work carefully, and write rigorous philosophical analyses of live debates about persons, machines, animals, and mental life.", "topics": [{"id": "1dd3be54-e7dc-4b3c-bf90-d4960f5ed535", "type": "topic", "title": "What Philosophy of Mind Studies: Questions, Methods, and Stakes", "description": "This opening topic frames philosophy of mind as an inquiry into consciousness, thought, agency, selfhood, and their relation to bodies, brains, behavior, language, and artificial systems.", "children": [{"id": "45cd9c2c-bb4b-43ab-bf4f-74e34cf80cd2", "type": "subtopic", "title": "Core questions", "children": [{"id": "7a0fe9b5-d90d-4d22-a7c7-ff65460d45f0", "type": "concept", "title": "What are minds, mental states, and persons?"}, {"id": "1e223ad6-4ba3-48c2-b811-8bd79f7b9f4e", "type": "concept", "title": "How do consciousness, thought, emotion, and agency relate?"}, {"id": "4c293dc3-a692-405e-aaf2-7cb4022037bf", "type": "concept", "title": "What makes a system a subject rather than merely an object?"}], "description": "The point is to establish the terrain before students choose sides in debates."}, {"id": "1797e1bd-746c-422e-9be9-2e98542e1ab5", "type": "subtopic", "title": "Levels of analysis", "children": [{"id": "01340ea2-4ed1-49dd-aed3-c799bb3a4663", "type": "concept", "title": "First-person and third-person perspectives"}, {"id": "8f885146-b4e8-49e6-9205-5d967cf5b7b9", "type": "concept", "title": "Personal, subpersonal, neural, and computational levels"}, {"id": "680a3209-75d3-4bc8-9297-aa67e5e9a11b", "type": "concept", "title": "Conceptual analysis, thought experiments, and empirical evidence"}], "description": "Students learn to distinguish philosophical, psychological, neural, computational, and social explanations."}, {"id": "5867b687-5484-41b7-94b1-758370957245", "type": "subtopic", "title": "Why it matters", "children": [{"id": "df461b1e-b1f1-4de5-942c-3ab10458b164", "type": "concept", "title": "Consciousness and value"}, {"id": "3a1b7818-c7aa-4abc-a8d4-f46c4486dd16", "type": "concept", "title": "Responsibility and agency"}, {"id": "bc110eaf-efef-4dd8-b7f5-cf730de79ecf", "type": "concept", "title": "AI, medicine, law, disability, and social practice"}], "description": "Philosophy of mind shapes how we understand ourselves, other people, animals, machines, and moral status."}]}, {"id": "976e02de-e715-4638-83fa-11de9ad44299", "type": "topic", "title": "The Mind-Body Problem: Dualism, Physicalism, and Explanatory Strategy", "description": "Students learn the central metaphysical problem of the course: how mental life fits into a world described by the physical sciences.", "children": [{"id": "11340bb5-2d03-44be-afae-b40199486c92", "type": "subtopic", "title": "Dualist views", "children": [{"id": "7e214f4a-085d-4f8e-b5b4-8797f656aa07", "type": "concept", "title": "Substance dualism"}, {"id": "3c47814e-5d0f-4820-afaf-fe1f1feae2a2", "type": "concept", "title": "Property dualism"}, {"id": "5cb8587b-bdfc-4c23-96da-586cc0ebac7d", "type": "concept", "title": "Interaction, pairing, and causal closure objections"}], "description": "Students learn why some philosophers think mind cannot be reduced to matter."}, {"id": "a90298ec-fb2c-4fbd-b3c2-2d0312c5219f", "type": "subtopic", "title": "Physicalist views", "children": [{"id": "a72bc5ad-6f88-4c38-b9a5-47e2457a7c21", "type": "concept", "title": "Type and token physicalism"}, {"id": "defaa107-07b6-4d96-9929-9ca8fb32ce48", "type": "concept", "title": "Supervenience and realization"}, {"id": "972f10b3-b256-46f4-8513-be90cd040410", "type": "concept", "title": "Nonreductive physicalism"}], "description": "Physicalism tries to place mind inside the natural world without eliminating what matters about experience."}, {"id": "6b1c6b1f-e5f6-4408-9f09-bd213e0352a0", "type": "subtopic", "title": "Explanatory strategies", "children": [{"id": "209c6249-0c40-4eff-85a5-76657a2f250a", "type": "concept", "title": "Reduction, identity, and realization"}, {"id": "ebc5cad1-2a2e-4005-8ba8-098c0bf1ebc4", "type": "concept", "title": "Conceptual analysis versus empirical discovery"}, {"id": "342c233f-b93c-449d-a559-28eef04a00fa", "type": "concept", "title": "Explanatory gaps and burden of proof"}], "description": "The course compares what different theories count as a successful explanation."}]}, {"id": "12dcc664-348e-471c-8915-b0cca266c0df", "type": "topic", "title": "Behaviorism, Identity Theory, and Functionalism", "description": "This topic studies three major twentieth-century attempts to naturalize the mind through behavior, brain states, and functional organization.", "children": [{"id": "bcdafe8c-4cba-4131-9e2b-15f824b0b3ce", "type": "subtopic", "title": "Behaviorism", "children": [{"id": "7df2ec39-e10e-44bc-9b94-bc0a5d3cf9a7", "type": "concept", "title": "Logical behaviorism"}, {"id": "6fc67271-3142-4008-840e-31728f276728", "type": "concept", "title": "Methodological behaviorism"}, {"id": "0f50ff9e-bad6-4c6d-9b90-b760a83c4e8c", "type": "concept", "title": "Private mental states and hidden causes"}], "description": "Behaviorism attempts to explain mental life through behavior, dispositions, and public criteria."}, {"id": "b3b1de07-7dbd-4008-8113-d3b5203812b5", "type": "subtopic", "title": "Identity theory", "children": [{"id": "2affd8ac-5d7b-42e6-8220-d0b5b3af9f19", "type": "concept", "title": "Type identity and multiple realization"}, {"id": "8e9cd1d7-1b58-442b-9534-5d375fe25d00", "type": "concept", "title": "Token identity"}, {"id": "dcd78018-be78-4e17-b0be-47db23e91517", "type": "concept", "title": "Pain, C-fibers, and neural variability"}], "description": "Identity theorists identify mental states with brain states or neural processes."}, {"id": "63746651-db87-4666-af64-91276c8a26c1", "type": "subtopic", "title": "Functionalism", "children": [{"id": "65c53295-0000-4f28-b2c0-770f1dbe2cf2", "type": "concept", "title": "Inputs, outputs, and internal states"}, {"id": "fc761b96-9a3d-4f33-b268-99dbd1be9fd3", "type": "concept", "title": "Multiple realizability"}, {"id": "c0c78b00-c603-4872-ac05-c3341d2ff1e9", "type": "concept", "title": "Machine functionalism and computational models"}], "description": "Functionalism explains mental states by their causal roles."}]}, {"id": "fce19730-56c7-4fc0-a000-cb01ee45d57c", "type": "topic", "title": "Consciousness, Qualia, and the Hard Problem", "description": "Students examine subjective experience, phenomenal character, explanatory gaps, and the arguments that make consciousness philosophically difficult.", "children": [{"id": "93d2ff6d-89e2-43f9-a7bb-b10f5ee0abb6", "type": "subtopic", "title": "Phenomenal consciousness", "children": [{"id": "93e07884-2157-407a-8e44-d2c50a4a2a0c", "type": "concept", "title": "Qualia and subjective character"}, {"id": "9ababd17-cd05-42e4-94e2-2789bffb630a", "type": "concept", "title": "Access consciousness and phenomenal consciousness"}, {"id": "c231d480-154f-4075-b567-80ac8018c208", "type": "concept", "title": "Creature consciousness and state consciousness"}], "description": "Students study what it is like to have an experience."}, {"id": "d4932d7c-14ff-4655-9586-bf53d90503c0", "type": "subtopic", "title": "Classic arguments", "children": [{"id": "0c50e350-dadc-46c6-8be1-f4ffbb099b58", "type": "concept", "title": "Mary and the knowledge argument"}, {"id": "1c169c39-2828-4fe5-ac4f-30a7688366af", "type": "concept", "title": "Zombies and conceivability"}, {"id": "08a45fe7-80af-4c7b-9259-f4e92487ea84", "type": "concept", "title": "Inverted spectrum and absent qualia"}], "description": "The central arguments test whether physical information can capture experience."}, {"id": "4a541c6d-38aa-4651-b283-eabc0baeed5d", "type": "subtopic", "title": "The hard problem", "children": [{"id": "7ec12980-c066-4cb0-b27e-33468c87ab6c", "type": "concept", "title": "Easy problems and hard problem"}, {"id": "e1d37113-f3cc-4c80-966f-3b053c9997d0", "type": "concept", "title": "Explanatory gap"}, {"id": "1473d0ab-740d-4cb2-ab4f-545d41686351", "type": "concept", "title": "Illusionism, panpsychism, and property dualism as responses"}], "description": "Students learn why explaining functions may not explain experience itself."}]}, {"id": "508bbc7a-b811-4ccf-8436-af1831146922", "type": "topic", "title": "Intentionality, Mental Representation, and Content", "description": "This topic asks how mental states can be about objects, properties, possibilities, meanings, and absent or fictional things.", "children": [{"id": "ce35d623-6984-4e21-87d5-1950b99ce6df", "type": "subtopic", "title": "Aboutness", "children": [{"id": "59101036-b146-4d6f-ac5d-7835fbc97259", "type": "concept", "title": "Belief, desire, fear, hope, and imagination"}, {"id": "39fef030-3416-423a-ae07-2f6f739a896b", "type": "concept", "title": "Reference to absent or nonexistent objects"}, {"id": "8abd365e-0446-404f-b109-f4444b8e0b0d", "type": "concept", "title": "Directedness and conditions of satisfaction"}], "description": "Intentionality is the mind's directedness toward things, properties, possibilities, and meanings."}, {"id": "78ad26b2-fe49-481c-852d-7b83cdffdfb3", "type": "subtopic", "title": "Theories of content", "children": [{"id": "d8f7713e-2496-4f72-9c6a-9dd4dcbeebbb", "type": "concept", "title": "Causal and informational theories"}, {"id": "059b6332-f709-4158-88e6-bda89ce905d8", "type": "concept", "title": "Teleosemantics"}, {"id": "76b28e2c-f27b-4e1b-808a-b331be3aac03", "type": "concept", "title": "Conceptual role and inferential role semantics"}], "description": "Students compare major accounts of how mental content is fixed."}, {"id": "7a385638-bd5e-4255-ad56-151e14972d67", "type": "subtopic", "title": "Naturalizing intentionality", "children": [{"id": "e7a7d126-be89-4151-ab27-5fed5cedeb19", "type": "concept", "title": "Misrepresentation"}, {"id": "55d78942-34a1-4107-8ae1-7063614e70c7", "type": "concept", "title": "Original versus derived intentionality"}, {"id": "fa3028af-dbbe-412e-b405-4243a80a2c02", "type": "concept", "title": "Content externalism and twin cases"}], "description": "This subtopic asks whether aboutness can be explained in natural-scientific terms."}]}, {"id": "7a6dc484-ba68-4abe-990c-3ff8376085ee", "type": "topic", "title": "Mental Causation, Reduction, Emergence, and Explanation", "description": "Students study whether mental states genuinely cause action and how mental explanations relate to physical, neural, computational, and personal-level explanations.", "children": [{"id": "d183c093-dd11-4f93-95f4-bf73a17cc730", "type": "subtopic", "title": "Mental causation", "children": [{"id": "74e44534-1412-4132-96c3-66bf9057e286", "type": "concept", "title": "Causal exclusion problem"}, {"id": "afa274fc-39d2-42de-990e-e1371d346467", "type": "concept", "title": "Overdetermination"}, {"id": "4b0e801d-17aa-490b-ba3b-e79151d2c971", "type": "concept", "title": "Reasons as causes"}], "description": "The point is to understand whether reasons, beliefs, desires, and experiences make a causal difference."}, {"id": "cf13fee8-d6e9-45a8-8096-6600412ce108", "type": "subtopic", "title": "Reduction and emergence", "children": [{"id": "a84366dc-6947-47b2-b972-f08bb4db7fee", "type": "concept", "title": "Bridge laws and reduction"}, {"id": "db4f1455-282b-44a6-a0eb-71a3a65334d7", "type": "concept", "title": "Multiple realizability"}, {"id": "572b11be-6475-48d6-b63a-b2cf78868917", "type": "concept", "title": "Emergent properties and downward causation"}], "description": "Students study whether mental properties reduce to physical properties or emerge from them."}, {"id": "18bc6ffe-2187-4fcd-960c-c2be6470b8f6", "type": "subtopic", "title": "Explanation in practice", "children": [{"id": "8878ab16-3564-4ded-87a6-0b8c8b999a79", "type": "concept", "title": "Mechanistic explanation"}, {"id": "c3654c87-69b0-4478-97b1-9f1443687f5b", "type": "concept", "title": "Computational explanation"}, {"id": "3a25636c-c607-48be-9934-a05a943ebd57", "type": "concept", "title": "Narrative and personal-level explanation"}], "description": "Advanced work connects metaphysical debates to actual explanation in psychology and neuroscience."}]}, {"id": "098ffa8f-c177-46ba-b6e7-d26bb81b3593", "type": "topic", "title": "Personal Identity, Selfhood, and Agency", "description": "This topic connects philosophy of mind to questions about what a person is, what persists over time, and how selves act, choose, and own experiences.", "children": [{"id": "fa003e86-7723-473a-bf98-df297f426c82", "type": "subtopic", "title": "Persistence over time", "children": [{"id": "bfaaad9e-2edc-4caf-84d0-3d0120bab599", "type": "concept", "title": "Memory and psychological continuity"}, {"id": "49e67cd5-d3e6-44fa-9992-0a1ea6758e46", "type": "concept", "title": "Bodily continuity and animalism"}, {"id": "49684458-1caa-47d8-aa19-e5e5add9aaca", "type": "concept", "title": "Fission, teleportation, and puzzle cases"}], "description": "Students ask what makes someone the same person across psychological and bodily change."}, {"id": "6dab81c4-baca-469e-af71-0b6a7963b1af", "type": "subtopic", "title": "Self and ownership", "children": [{"id": "6d7e5da5-d226-4ad3-92d3-d5e1d8b6b594", "type": "concept", "title": "Minimal self and narrative self"}, {"id": "553aa314-c277-47ca-b0d4-b6534ccde2d7", "type": "concept", "title": "Body ownership and agency"}, {"id": "b78c39e1-8756-4e2e-9262-0f03e1e2dc6e", "type": "concept", "title": "Dissociation, depersonalization, and self-models"}], "description": "This subtopic explores the sense of mineness in experience and action."}, {"id": "9b62f747-ad97-4a45-b9b6-c64263287139", "type": "subtopic", "title": "Agency and responsibility", "children": [{"id": "776134ae-ee7c-4906-be97-4949f4391f93", "type": "concept", "title": "Intentions and reasons"}, {"id": "0c44d429-fd86-41de-b712-b29300228dc1", "type": "concept", "title": "Free will and control"}, {"id": "c5df6790-5dd4-44a8-8375-17576676ae36", "type": "concept", "title": "Addiction, compulsion, and diminished agency"}], "description": "Students connect mind to action, intention, choice, and moral responsibility."}]}, {"id": "b7ebdfcf-e2a9-48d6-b16a-7dfe0483b180", "type": "topic", "title": "Perception, Embodiment, and the Extended Mind", "description": "Students examine perception and cognition as embodied, situated, action-oriented, and possibly extended beyond the biological brain.", "children": [{"id": "8a20b642-50e8-463c-9067-b7b4a2fcd93f", "type": "subtopic", "title": "Perception", "children": [{"id": "dc0845f3-9455-420b-8804-9d70ffa49cde", "type": "concept", "title": "Sense data and direct realism"}, {"id": "b8c6e0ba-9b93-4b2a-ae7c-6c51e954a0e6", "type": "concept", "title": "Representationalism and naive realism"}, {"id": "4c1f4147-4d54-423e-9a4f-83e3e44310bd", "type": "concept", "title": "Perceptual constancy, illusion, and hallucination"}], "description": "Perception is a testing ground for direct realism, representation, prediction, and embodied action."}, {"id": "9c42ab55-f747-4db9-89e2-6e61673d20e8", "type": "subtopic", "title": "Embodied cognition", "children": [{"id": "a7fb2c9f-33fc-4da7-bc92-fe0ae5018856", "type": "concept", "title": "Sensorimotor accounts"}, {"id": "98f30be5-5748-45d9-a506-36ee514b7fa8", "type": "concept", "title": "Body schema and affordances"}, {"id": "b68994cc-afe0-4b75-be2c-db608477292b", "type": "concept", "title": "Gesture, posture, and action-oriented cognition"}], "description": "Students study how the body shapes thought rather than merely carrying the brain around."}, {"id": "a758bcd0-4904-40d2-841a-9cab7a00e323", "type": "subtopic", "title": "Extended mind", "children": [{"id": "a0cf4d9d-7036-43b7-b4b3-34e92133c515", "type": "concept", "title": "Clark and Chalmers style cases"}, {"id": "5d35302a-060d-43bd-8b8c-ab09be18d90d", "type": "concept", "title": "Parity principle and cognitive integration"}, {"id": "e6d4e8e0-8ade-422f-bd7d-7fdb9fcaa3af", "type": "concept", "title": "Boundaries of the cognitive system"}], "description": "This debate asks whether tools, notebooks, phones, diagrams, and environments can partly constitute cognition."}]}, {"id": "2c67a059-9910-43a5-b749-961e4272a1ef", "type": "topic", "title": "Emotion, Affect, Pain, and the Body", "description": "This topic treats affective and bodily experience as central to mind, not merely as optional add-ons to cognition.", "children": [{"id": "6eadf81a-5e69-4a4c-84a7-74247aeaa861", "type": "subtopic", "title": "Emotion theories", "children": [{"id": "02347699-dc1c-42a8-bc1b-ed5777553313", "type": "concept", "title": "James-Lange and bodily feeling views"}, {"id": "51d770da-d2c1-4cfa-be73-ae72d711f325", "type": "concept", "title": "Cognitivist and appraisal theories"}, {"id": "e258efd3-c870-4241-b19f-4905fff671b2", "type": "concept", "title": "Basic emotion and constructionist approaches"}], "description": "Students compare bodily, cognitive, evaluative, and constructed accounts of emotion."}, {"id": "30bb35d3-4678-4533-a20b-32876451e713", "type": "subtopic", "title": "Pain and bodily awareness", "children": [{"id": "cd5b8978-c659-4dd4-a213-27472c47d871", "type": "concept", "title": "Pain as sensation versus perception"}, {"id": "53ac3bc5-3063-4e5d-964d-65133ec41c85", "type": "concept", "title": "Pain unpleasantness"}, {"id": "2fc0df33-2cf1-4c14-a893-9a6f5f574480", "type": "concept", "title": "Chronic pain, phantom pain, and bodily disruption"}], "description": "Pain is philosophically important because it is sensory, affective, evaluative, and action-guiding."}, {"id": "dd98eae0-4f92-4426-8ea3-7a524ea30b4f", "type": "subtopic", "title": "Affect and rationality", "children": [{"id": "ffaa9274-de1e-4094-9821-571985568cfd", "type": "concept", "title": "Mood and attention"}, {"id": "75ddcd36-4ce4-4407-9d4d-63a7f07ee70c", "type": "concept", "title": "Affective intentionality"}, {"id": "bc340efd-7c57-4cbc-8cf4-60d8ab41d7d3", "type": "concept", "title": "Emotion, ethics, and social cognition"}], "description": "The point is to show that emotion can be evidence, motivation, bias, and bodily orientation."}]}, {"id": "a5e51783-7305-4fd4-a169-a365db7962dd", "type": "topic", "title": "Language, Thought, Concepts, and Inner Speech", "description": "Students explore how language relates to thought, whether thinking requires symbols or concepts, and how linguistic capacities shape mental life.", "children": [{"id": "0ea66109-621a-4834-80ca-9b417cdb1fd7", "type": "subtopic", "title": "Language and thought", "children": [{"id": "c32bf5bd-7f0c-4ada-b05b-18fea206017a", "type": "concept", "title": "Language of thought hypothesis"}, {"id": "a87abeb1-26b9-4873-bcff-de2f923c15e0", "type": "concept", "title": "Concept possession"}, {"id": "bfb9b804-5e15-44e8-8251-c2415ed3e004", "type": "concept", "title": "Nonlinguistic cognition"}], "description": "Students examine whether thought depends on language or whether language expresses prior thought."}, {"id": "39726243-50ee-40b1-932c-56634c34efba", "type": "subtopic", "title": "Concepts and categories", "children": [{"id": "92a9d1b6-084e-48cb-b0d4-494244174b25", "type": "concept", "title": "Prototype, exemplar, and theory theories"}, {"id": "0c99d10a-dc52-4c4d-a0c2-8e207d7d1e53", "type": "concept", "title": "Conceptual versus nonconceptual content"}, {"id": "59936889-2578-40f9-99ce-4ee9fe041637", "type": "concept", "title": "Natural kinds and social categories"}], "description": "Concepts mediate perception, reasoning, memory, and action."}, {"id": "7c98395b-625c-48a2-be47-cc8329031ecc", "type": "subtopic", "title": "Inner speech and self-interpretation", "children": [{"id": "fc42d581-6277-4527-9276-7170b821102a", "type": "concept", "title": "Inner monologue and cognitive control"}, {"id": "4e2b0731-db40-4fa5-b4e9-9d9016a3ac0d", "type": "concept", "title": "Verbal thought and imagery"}, {"id": "081fd1f2-d3e9-4a46-88f2-8af04e1a9469", "type": "concept", "title": "Narrative self and interpretive agency"}], "description": "This subtopic connects language to consciousness, agency, and self-regulation."}]}, {"id": "bfd8ec18-7db7-4523-b5c2-36fa849fab30", "type": "topic", "title": "Neuroscience, Cognitive Psychology, and Methods for Studying Mind", "description": "This topic gives students enough empirical literacy to evaluate claims from neuroscience, psychology, cognitive science, and brain imaging without reducing philosophy to data summary.", "children": [{"id": "83696a87-57f2-448f-861f-8319e8029705", "type": "subtopic", "title": "Brain and behavior methods", "children": [{"id": "56621cf7-6ac0-4482-a171-83fe13a10248", "type": "concept", "title": "Lesions, stimulation, EEG, fMRI, and single-cell recording"}, {"id": "9be4f5e7-14bf-4fe1-96d6-c718c3e635d2", "type": "concept", "title": "Behavioral experiments and reaction time"}, {"id": "f5e14cc5-5c5a-4b4a-9000-31e32579ee64", "type": "concept", "title": "Computational modeling and cognitive tasks"}], "description": "Students learn what different empirical tools can and cannot show."}, {"id": "4f1a9928-2721-4c4d-9e84-fe1587c556df", "type": "subtopic", "title": "Cognitive systems", "children": [{"id": "ecf38f4c-008a-42a2-aadc-54d798c8ef42", "type": "concept", "title": "Attention and working memory"}, {"id": "6f5b078a-56b1-48ad-8577-ee391b5bcc44", "type": "concept", "title": "Long-term memory and concepts"}, {"id": "a3ba0c9e-c228-43a0-9967-44ef6074abf8", "type": "concept", "title": "Reasoning, problem solving, and decision making"}], "description": "This subtopic connects philosophy with attention, memory, language, perception, and decision making."}, {"id": "07606ffd-0722-4808-af3b-79eaf01ad1ed", "type": "subtopic", "title": "Methodological caution", "children": [{"id": "ecbcbe51-7747-45f4-8245-7fbecfe8706f", "type": "concept", "title": "Reverse inference and localization limits"}, {"id": "1d14404e-5e9f-4acf-8135-2ec30559ffd6", "type": "concept", "title": "Replication and ecological validity"}, {"id": "c823d590-1fe6-467c-800f-0bccc80c2aaf", "type": "concept", "title": "Philosophical interpretation of empirical results"}], "description": "Students learn to resist both armchair isolation and naive brain-scan triumphalism."}]}, {"id": "920db6a1-a238-4b4b-91a3-a5f72bc1d348", "type": "topic", "title": "Artificial Intelligence, Computation, and Machine Minds", "description": "Students examine whether machines can think, understand, be conscious, or possess agency, using classical AI, connectionism, contemporary deep learning, and language models as test cases.", "children": [{"id": "906e3133-012b-4dfe-bc56-ab17a79124e8", "type": "subtopic", "title": "Classical AI and computation", "children": [{"id": "a77d596d-b545-4eaf-905e-0b186a33341c", "type": "concept", "title": "Turing test"}, {"id": "48907ad7-d6e7-4c32-a9a1-c0fb7432de2c", "type": "concept", "title": "Physical symbol systems"}, {"id": "a2e6e4fd-e317-439d-9720-6159f24eabcc", "type": "concept", "title": "Computation, implementation, and syntax"}], "description": "Students examine whether cognition is computation over representations."}, {"id": "721c0c5e-04b4-417e-aa66-20adb868a353", "type": "subtopic", "title": "Chinese room and understanding", "children": [{"id": "7b6f6a1c-791e-4d1b-aa7e-91c8b14025c3", "type": "concept", "title": "Searle's Chinese room"}, {"id": "14664162-ff2b-4e50-b66d-5178a7556672", "type": "concept", "title": "Systems replies and robot replies"}, {"id": "dc5fb6d2-0211-44cc-b78b-2b2323f12bc9", "type": "concept", "title": "Syntax, semantics, and grounding"}], "description": "This debate tests whether appropriate input-output behavior is enough for understanding."}, {"id": "72a0b4d8-68b9-4a65-b95e-f77919a33740", "type": "subtopic", "title": "Contemporary AI and machine minds", "children": [{"id": "299b4bf6-c758-49c1-9596-f209d937e7dd", "type": "concept", "title": "Neural networks and representation"}, {"id": "5091f013-41b6-47a4-974a-eed4766be762", "type": "concept", "title": "Transformers and large language models"}, {"id": "26535d67-f1cd-435d-b548-facd504ee370", "type": "concept", "title": "Consciousness, agency, alignment, and moral status"}], "description": "Students evaluate deep learning and language models through philosophy of mind questions."}]}, {"id": "8c669aa9-8e4b-4bd0-a30d-fd3792f366e1", "type": "topic", "title": "Animal Minds, Other Minds, and Social Cognition", "description": "This topic expands the course beyond individual adult human minds by asking how we know other minds and how mindedness appears in animals, infants, groups, and social interaction.", "children": [{"id": "3fa6029b-4da0-492a-8e46-098f61ca1276", "type": "subtopic", "title": "Other minds", "children": [{"id": "e4cd120f-60a7-4e44-ae0c-83f953d166d4", "type": "concept", "title": "Analogy and inference"}, {"id": "7734b1a5-627c-40a9-90d4-bd59cc4f551f", "type": "concept", "title": "Behavior and expression"}, {"id": "c5152a63-e859-4bd4-b110-dca2c8a75431", "type": "concept", "title": "Simulation theory and theory theory"}], "description": "The problem of other minds asks how we know that anyone else has mental states."}, {"id": "e8c0ca94-d22e-4adb-ac8c-d5a301550585", "type": "subtopic", "title": "Animal cognition", "children": [{"id": "896cb8b9-f556-48c1-9ae3-68043c7275ed", "type": "concept", "title": "Pain, emotion, and consciousness in animals"}, {"id": "4783ee5b-7831-4683-a8ab-f31d2e6e14a9", "type": "concept", "title": "Tool use, memory, and problem solving"}, {"id": "b479ef00-790a-4cae-9a0f-8ae40215c30e", "type": "concept", "title": "Comparative cognition and moral status"}], "description": "Students compare human and nonhuman minds without assuming either sameness or radical discontinuity."}, {"id": "ec1d9101-efc3-4b18-9154-ceba4ef2326f", "type": "subtopic", 